using System.ComponentModel.DataAnnotations;using StbMonitoring.Domain.Entities;
namespace StbMonitoring.Application.Contracts;
public sealed record CreateSystemRequest([Required,RegularExpression("^[A-Za-z][A-Za-z0-9_]{2,59}$")]string Code,[Required]string Name,string Description,SystemEnvironment Environment,SystemCriticality Criticality,string? Owner);
public sealed record UpdateSystemRequest([Required,RegularExpression("^[A-Za-z][A-Za-z0-9_]{2,59}$")]string Code,[Required]string Name,string Description,SystemEnvironment Environment,SystemCriticality Criticality,string? Owner);
public sealed record SystemResponse(Guid Id,string Code,string Name,string Description,SystemEnvironment Environment,SystemCriticality Criticality,string? Owner,bool MonitoringEnabled,bool IsArchived,MonitoringStatus Status,DateTime? LastCheckedAt,int EndpointCount,int UpCount,int DegradedCount,int DownCount);
public sealed record UpsertEndpointRequest([Required]string Name,[Required,Url]string Url,CheckType CheckType,[Required]string HttpMethod,[Range(100,599)]int ExpectedStatusCode,[Range(1,300)]int TimeoutSeconds,[Range(10,86400)]int IntervalSeconds,[Range(1,int.MaxValue)]int DegradedThresholdMs,[Range(1,int.MaxValue)]int DownThresholdMs,bool IsCritical,string? ExpectedJsonProperty,string? ExpectedJsonValue);
public sealed record EndpointResponse(Guid Id,Guid SystemId,string Name,string Url,CheckType CheckType,string HttpMethod,int ExpectedStatusCode,int TimeoutSeconds,int IntervalSeconds,int DegradedThresholdMs,int DownThresholdMs,bool IsCritical,bool IsActive,string? ExpectedJsonProperty,string? ExpectedJsonValue,MonitoringStatus Status,DateTime? LastCheckedAt,DateTime NextCheckAt,long? LastDurationMs,string? LastError);
public sealed record CheckResultResponse(Guid Id,Guid SystemId,Guid EndpointId,string EndpointName,MonitoringStatus Status,bool Success,DateTime StartedAt,DateTime CompletedAt,long DurationMs,int? HttpStatusCode,string? ErrorType,string? ErrorMessage,bool TriggeredManually,Guid? TriggeredByUserId,string? Metadata);
public sealed record SystemDetailResponse(SystemResponse System,IReadOnlyCollection<EndpointResponse> Endpoints,IReadOnlyCollection<CheckResultResponse> RecentResults);
public sealed record CheckExecution(Guid EndpointId,MonitoringStatus Status,bool Success,DateTime StartedAt,DateTime CompletedAt,long DurationMs,int? HttpStatusCode,string? ErrorType,string? ErrorMessage,string? Metadata);
